/**
 * `omg factory setup --workflows`: renders the cloud heartbeat (a scheduled
 * GitHub workflow, or an Azure DevOps pipeline) from templates/workflows and
 * templates/pipelines, and plans its single file.
 *
 * Safety shape: the generated file runs only `omg factory check` (and, in
 * triage mode, `omg factory triage --apply`), pinned to the installed package
 * version, with read-only permissions unless triage mode asks for a write
 * scope. A file this command did not write (no marker line) is never replaced
 * without `force`; nothing outside the one target path is written.
 */

import { existsSync, lstatSync, readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { SetupError } from './guard.js';
import { lineDiff, type PlannedWrite } from './write.js';

export type HeartbeatMode = 'read-only' | 'triage';
export type HeartbeatForge = 'github' | 'azure-devops';

export const DEFAULT_HEARTBEAT_CRON = '17 */2 * * *';
/** The first omg release that has `omg factory triage`; triage mode refuses to pin anything older. */
export const HEARTBEAT_TRIAGE_MIN_VERSION = '5.22.0';
export const HEARTBEAT_MARKER = '# omg-factory-heartbeat: generated by `omg factory setup --workflows`';

const TARGETS: Record<HeartbeatForge, { path: string; template: string; step: string; dir: string }> = {
  github: { path: '.github/workflows/omg-factory-heartbeat.yml', template: 'omg-factory-heartbeat.yml', step: 'omg-factory-heartbeat.triage-step.yml', dir: 'workflows' },
  'azure-devops': { path: '.azure-pipelines/omg-factory-heartbeat.yml', template: 'omg-factory-heartbeat.azure-pipelines.yml', step: 'omg-factory-heartbeat.triage-step.yml', dir: 'pipelines' },
};

export interface HeartbeatOptions {
  mode: HeartbeatMode;
  cron: string;
  /** The exact package version the generated file installs. */
  version: string;
  /** Azure DevOps only: the one branch whose YAML the schedule may run (the default branch). */
  branch?: string;
  force: boolean;
}

export interface HeartbeatPlan {
  /** Repository-relative target path (forward slashes). */
  relPath: string;
  write?: PlannedWrite;
  /** `create`, `update` (a file we wrote), `overwrite` (foreign, --force) or `unchanged`. */
  action: 'create' | 'update' | 'overwrite' | 'unchanged';
  /** Non-fatal findings about the schedule (for example, more often than every 15 minutes). */
  warnings: string[];
}

const CRON = /^(?:[0-9*/,-]+ ){4}[0-9*/,-]+$/;
const VERSION = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/;
/** The --omg-version override: plain x.y.z, no prerelease, no leading zeros. */
const STRICT_SEMVER = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;
const BRANCH = /^[A-Za-z0-9._/-]+$/;
/** minute, hour, day of month, month, day of week (0 and 7 are Sunday). */
const CRON_RANGES: ReadonlyArray<readonly [string, number, number]> = [['minute', 0, 59], ['hour', 0, 23], ['day of month', 1, 31], ['month', 1, 12], ['day of week', 0, 7]];
/** Runs closer together than this draw a warning. */
const MIN_COMFORTABLE_GAP_MINUTES = 15;

export function validateOmgVersionOverride(raw: string): string {
  if (!STRICT_SEMVER.test(raw)) throw new SetupError(2, `--omg-version must be an exact x.y.z version, got ${JSON.stringify(raw)}`);
  return raw;
}

/** -1, 0 or 1; a prerelease sorts before its release. */
function compareVersions(a: string, b: string): number {
  const parse = (v: string): [number[], boolean] => [v.split('-')[0].split('.').map(Number), v.includes('-')];
  const [na, pa] = parse(a);
  const [nb, pb] = parse(b);
  for (let i = 0; i < 3; i++) if (na[i] !== nb[i]) return na[i] < nb[i] ? -1 : 1;
  return pa === pb ? 0 : pa ? -1 : 1;
}

/** The values one cron field selects, or a SetupError naming the field. */
function expandCronField(text: string, name: string, lo: number, hi: number): Set<number> {
  const bad = (why: string): never => { throw new SetupError(2, `--cron ${name} field ${JSON.stringify(text)}: ${why} (allowed ${lo}-${hi})`); };
  const out = new Set<number>();
  for (const item of text.split(',')) {
    const m = /^(\*|(\d+)(?:-(\d+))?)(?:\/(\d+))?$/.exec(item);
    if (!m) return bad('not a number, range, list or step');
    const step = m[4] === undefined ? 1 : Number(m[4]);
    if (step < 1) return bad('a step must be at least 1');
    const from = m[1] === '*' ? lo : Number(m[2]);
    const to = m[1] === '*' ? hi : m[3] === undefined ? (m[4] === undefined ? from : hi) : Number(m[3]);
    if (from < lo || from > hi || to < lo || to > hi) return bad('out of range');
    if (from > to) return bad('a range must not run backwards');
    for (let v = from; v <= to; v += step) out.add(v);
  }
  return out;
}

/** Validates the five fields and returns the warnings (the schedule runs closer than 15 minutes apart). */
export function checkCron(cron: string): string[] {
  if (!CRON.test(cron)) throw new SetupError(2, `--cron must be five cron fields (digits, *, /, comma, dash), got ${JSON.stringify(cron)}`);
  const sets = cron.split(' ').map((field, i) => expandCronField(field, CRON_RANGES[i][0], CRON_RANGES[i][1], CRON_RANGES[i][2]));
  const times = [...sets[1]].flatMap((h) => [...sets[0]].map((m) => h * 60 + m)).sort((a, b) => a - b);
  // Day, month and weekday filters only remove runs, so ignoring them can only over-warn.
  let gap = times.length > 1 ? times[0] + 1440 - times[times.length - 1] : Infinity;
  for (let i = 1; i < times.length; i++) gap = Math.min(gap, times[i] - times[i - 1]);
  return gap < MIN_COMFORTABLE_GAP_MINUTES ? [`--cron ${JSON.stringify(cron)} can run every ${gap} minute${gap === 1 ? '' : 's'}: a heartbeat that often burns CI minutes and API quota; every ${MIN_COMFORTABLE_GAP_MINUTES} minutes or less often is advised`] : [];
}

export function parseHeartbeatMode(raw: string | undefined): HeartbeatMode {
  if (raw === undefined || raw === 'read-only') return 'read-only';
  if (raw === 'triage') return 'triage';
  throw new SetupError(2, `--mode must be read-only or triage, got ${JSON.stringify(raw)}`);
}

export function heartbeatPath(forge: HeartbeatForge): string {
  return TARGETS[forge].path;
}

/** templates/<dir> of the package, found by walking up from this module (src/, dist/ or the bundle). */
function templateDir(dir: string): string {
  let here = dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 6; i++) {
    const candidate = join(here, 'templates', dir);
    if (existsSync(candidate)) return candidate;
    here = dirname(here);
  }
  throw new SetupError(1, `cannot find the packaged templates/${dir} directory`);
}

/** The rendered file; inputs are validated first because they land in YAML. */
export function renderHeartbeat(forge: HeartbeatForge, o: Pick<HeartbeatOptions, 'mode' | 'cron' | 'version' | 'branch'>): string {
  checkCron(o.cron);
  if (!VERSION.test(o.version)) throw new SetupError(1, `cannot pin the omg version ${JSON.stringify(o.version)}: not an exact semver`);
  if (o.mode === 'triage' && compareVersions(o.version, HEARTBEAT_TRIAGE_MIN_VERSION) < 0) {
    throw new SetupError(2, `--mode triage needs omg >= ${HEARTBEAT_TRIAGE_MIN_VERSION} (the first release with omg factory triage), but the pinned version is ${o.version}: pass --omg-version <x.y.z> once a release that has it is published`);
  }
  // Azure DevOps runs a schedule from the YAML of every branch listed, so the list is the one default branch.
  const branch = o.branch ?? '';
  if (forge === 'azure-devops' && (!BRANCH.test(branch) || branch.includes('..'))) {
    throw new SetupError(2, `cannot schedule the pipeline on branch ${JSON.stringify(branch)}: expected letters, digits, ., _, / and - only, without ..`);
  }
  const target = TARGETS[forge];
  const dir = templateDir(target.dir);
  const template = readFileSync(join(dir, target.template), 'utf8').replace(/\r\n/g, '\n');
  const triage = o.mode === 'triage';
  const note = triage
    ? forge === 'github'
      ? '#   Triage mode is the opt-in write scope: issues: write lets `omg factory triage --apply` set labels.\n'
      : '# Triage mode is the opt-in write scope: `omg factory triage --apply` sets tags, so the build identity needs work item write access.\n'
    : '';
  const stepText = triage ? readFileSync(join(dir, target.step), 'utf8').replace(/\r\n/g, '\n') : '';
  const out = template
    .split('@@TRIAGE_STEP@@\n').join(stepText)
    // GitHub only: the read-only file has no triage step, so it must not reference one.
    .split('@@TRIAGE_ENV@@').join(triage ? '          TRIAGE_CODE: ${{ steps.triage.outputs.code }}\n' : '')
    .split('@@MODE_NOTE@@').join(note)
    .split('@@ISSUES@@').join(triage ? 'write' : 'read')
    .split('@@MODE@@').join(o.mode)
    .split('@@BRANCH@@').join(branch)
    .split('@@CRON@@').join(o.cron)
    .split('@@VERSION@@').join(o.version);
  if (out.includes('@@')) throw new SetupError(1, 'heartbeat template has an unfilled placeholder');
  return out;
}

/** Plans the one file. Throws SetupError(5) when a file we did not write is in the way and force is off. */
export function planHeartbeat(root: string, forge: HeartbeatForge, o: HeartbeatOptions): HeartbeatPlan {
  const relPath = TARGETS[forge].path;
  const after = renderHeartbeat(forge, o);
  const warnings = checkCron(o.cron);
  const path = join(root, ...relPath.split('/'));
  // Every directory on the way, and the file, must be a real one: a link would redirect the write.
  // lstat (not existsSync) so a dangling link is seen too; the first missing segment ends the walk.
  let p = root;
  for (const seg of relPath.split('/')) {
    p = join(p, seg);
    let linked: boolean;
    try {
      linked = lstatSync(p).isSymbolicLink();
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') break;
      throw new SetupError(5, `refusing to write ${relPath}: cannot inspect ${p} (${(err as NodeJS.ErrnoException).code ?? 'error'})`);
    }
    if (linked) throw new SetupError(5, `refusing to write ${relPath}: ${p} is a symlink or junction`);
  }
  if (!existsSync(path)) return { relPath, action: 'create', warnings, write: { path, scope: 'project', before: '', after, diff: lineDiff('', after) } };
  const raw = readFileSync(path, 'utf8');
  const before = raw.replace(/\r\n/g, '\n');
  if (before === after) return { relPath, action: 'unchanged', warnings };
  const ours = before.split('\n').some((line) => line.startsWith(HEARTBEAT_MARKER));
  if (!ours && !o.force) throw new SetupError(5, `${relPath} exists and was not written by omg factory setup --workflows; nothing written (pass --force to replace it)`);
  return { relPath, action: ours ? 'update' : 'overwrite', warnings, write: { path, scope: 'project', before: raw, after, diff: lineDiff(before, after) } };
}
